    --accent2:   #06b6d4;
    --green:     #10b981;
    --yellow:    #f59e0b;
    --red:       #ef4444;
    --text:      #f1f5f9;
    --muted:     #64748b;
  }

  body {
    font-family: 'Inter', sans-serif;
    background: var(--bg);
    color: var(--text);
    min-height: 100vh;
    overflow-x: hidden;
  }

  /* Ambient background glow */
  body::before {
    content: '';
    position: fixed; inset: 0;
    background:
      radial-gradient(ellipse 80% 50% at 20% 10%, rgba(99,102,241,0.12) 0%, transparent 60%),
      radial-gradient(ellipse 60% 40% at 80% 80%, rgba(6,182,212,0.10) 0%, transparent 60%);
    pointer-events: none;
  }

  /* ── NAV ── */
  nav {
    display: flex; align-items: center; justify-content: space-between;
    padding: 0 2rem;
    height: 64px;
    background: rgba(17,24,39,0.8);
    backdrop-filter: blur(12px);
    border-bottom: 1px solid var(--border);
    position: sticky; top: 0; z-index: 50;
  }
  .nav-logo { display: flex; align-items: center; gap: 0.6rem; font-weight: 700; font-size: 1.15rem; }
  .nav-logo-dot {
    width: 8px; height: 8px; border-radius: 50%;
    background: var(--accent);
    box-shadow: 0 0 10px var(--accent);
    animation: pulse-dot 2s ease-in-out infinite;
  }
  @keyframes pulse-dot {
    0%, 100% { transform: scale(1); opacity: 1; }
    50%       { transform: scale(1.4); opacity: 0.7; }
  }
  .nav-links { display: flex; gap: 2rem; }
  .nav-links a { color: var(--muted); text-decoration: none; font-size: 0.875rem; font-weight: 500; transition: color 0.2s; }
  .nav-links a:hover { color: var(--text); }
  .nav-badge {
    background: linear-gradient(135deg, var(--accent), var(--accent2));
    color: white; font-size: 0.75rem; font-weight: 600;
    padding: 0.35rem 0.9rem; border-radius: 9999px;
  }

  /* ── HERO ── */
  .hero {
    text-align: center;
    padding: 5rem 2rem 3rem;
  }
  .hero-tag {
    display: inline-flex; align-items: center; gap: 0.5rem;
    background: rgba(99,102,241,0.12);
    border: 1px solid rgba(99,102,241,0.3);
    color: #a5b4fc;
    font-size: 0.75rem; font-weight: 600;
    padding: 0.3rem 0.9rem; border-radius: 9999px;
    margin-bottom: 1.5rem;
    letter-spacing: 0.05em; text-transform: uppercase;
  }
  .hero h1 {
    font-size: clamp(2rem, 5vw, 3.5rem);
    font-weight: 800;
    line-height: 1.15;
    background: linear-gradient(135deg, #fff 30%, #a5b4fc 70%, #67e8f9);
    -webkit-background-clip: text; -webkit-text-fill-color: transparent;
    margin-bottom: 1rem;
  }
  .hero p {
    color: var(--muted); font-size: 1.05rem; max-width: 520px; margin: 0 auto 2.5rem;
    line-height: 1.7;
  }
  .hero-actions { display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap; }
  .btn-primary {
    background: linear-gradient(135deg, var(--accent), #818cf8);
    color: white; font-weight: 600; font-size: 0.9rem;
    padding: 0.75rem 1.75rem; border-radius: 10px; border: none;
    cursor: pointer; transition: transform 0.2s, box-shadow 0.2s;
    box-shadow: 0 4px 20px rgba(99,102,241,0.35);
  }
  .btn-primary:hover { transform: translateY(-2px); box-shadow: 0 8px 28px rgba(99,102,241,0.5); }
  .btn-secondary {
    background: var(--card); border: 1px solid var(--border);
    color: var(--text); font-weight: 600; font-size: 0.9rem;
    padding: 0.75rem 1.75rem; border-radius: 10px; cursor: pointer;
    transition: background 0.2s, border-color 0.2s;
  }
  .btn-secondary:hover { background: rgba(255,255,255,0.08); border-color: rgba(255,255,255,0.15); }

  /* ── STATUS STRIP ── */
  .status-strip {
    display: flex; justify-content: center; gap: 2rem; flex-wrap: wrap;
    padding: 1.2rem 2rem;
    background: rgba(16,185,129,0.05);
    border-top: 1px solid rgba(16,185,129,0.15);
    border-bottom: 1px solid rgba(16,185,129,0.15);
    margin-bottom: 3rem;
  }
  .status-item { display: flex; align-items: center; gap: 0.5rem; font-size: 0.8rem; color: var(--muted); }
  .status-dot {
    width: 7px; height: 7px; border-radius: 50%;
    animation: blink 2s ease-in-out infinite;
  }
  .status-dot.green { background: var(--green); box-shadow: 0 0 6px var(--green); }
  .status-dot.yellow { background: var(--yellow); box-shadow: 0 0 6px var(--yellow); }
  @keyframes blink { 0%,100%{opacity:1} 50%{opacity:0.4} }

  /* ── STATS GRID ── */
  .section { padding: 0 2rem 3rem; max-width: 1200px; margin: 0 auto; }
  .section-title { font-size: 0.7rem; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; color: var(--muted); margin-bottom: 1.2rem; }

  .stats-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 1rem; }
  .stat-card {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 1.25rem;
    transition: border-color 0.2s, transform 0.2s;
    position: relative; overflow: hidden;
  }
  .stat-card::before {
    content: ''; position: absolute; top: 0; left: 0; right: 0; height: 2px;
    border-radius: 12px 12px 0 0;
  }
  .stat-card.indigo::before { background: linear-gradient(90deg, var(--accent), #818cf8); }
  .stat-card.cyan::before   { background: linear-gradient(90deg, var(--accent2), #22d3ee); }
  .stat-card.green::before  { background: linear-gradient(90deg, var(--green), #34d399); }
  .stat-card.amber::before  { background: linear-gradient(90deg, var(--yellow), #fbbf24); }
  .stat-card:hover { border-color: rgba(255,255,255,0.15); transform: translateY(-2px); }
  .stat-label { font-size: 0.72rem; font-weight: 600; color: var(--muted); text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 0.6rem; }
  .stat-value { font-size: 2rem; font-weight: 800; line-height: 1; }
  .stat-value.indigo { color: #a5b4fc; }
  .stat-value.cyan   { color: #67e8f9; }
  .stat-value.green  { color: #6ee7b7; }
  .stat-value.amber  { color: #fcd34d; }
  .stat-sub { font-size: 0.72rem; color: var(--muted); margin-top: 0.35rem; }

  /* ── ACTIVITY FEED ── */
  .two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 1.5rem; margin-bottom: 3rem; }
  @media(max-width: 768px){ .two-col { grid-template-columns: 1fr; } }

  .panel {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 14px;
    padding: 1.5rem;
  }
  .panel-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 1.2rem; }
  .panel-title { font-size: 0.85rem; font-weight: 700; }
  .panel-badge {
    font-size: 0.65rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em;
    padding: 0.2rem 0.55rem; border-radius: 9999px;
  }
  .panel-badge.live { background: rgba(16,185,129,0.15); color: #34d399; border: 1px solid rgba(16,185,129,0.25); }
  .panel-badge.info { background: rgba(99,102,241,0.15); color: #a5b4fc; border: 1px solid rgba(99,102,241,0.25); }

  .feed-item {
    display: flex; align-items: flex-start; gap: 0.75rem;
    padding: 0.65rem 0;
    border-bottom: 1px solid var(--border);
    animation: fadeIn 0.4s ease;
  }
  .feed-item:last-child { border-bottom: none; }
  @keyframes fadeIn { from{opacity:0;transform:translateY(4px)} to{opacity:1;transform:translateY(0)} }
  .feed-icon {
    width: 28px; height: 28px; border-radius: 7px;
    display: flex; align-items: center; justify-content: center;
    font-size: 0.8rem; flex-shrink: 0;
  }
  .feed-icon.success { background: rgba(16,185,129,0.15); }
