  .feed-icon.info    { background: rgba(99,102,241,0.15); }
  .feed-body { flex: 1; min-width: 0; }
  .feed-msg { font-size: 0.78rem; font-weight: 500; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .feed-time { font-size: 0.68rem; color: var(--muted); margin-top: 0.1rem; }

  /* ── HOST INFO ── */
  .host-row { display: flex; align-items: center; justify-content: space-between; padding: 0.7rem 0; border-bottom: 1px solid var(--border); }
  .host-row:last-child { border-bottom: none; }
  .host-key { font-size: 0.75rem; color: var(--muted); font-weight: 500; }
  .host-val { font-size: 0.78rem; font-weight: 600; font-family: 'Courier New', monospace; color: #a5b4fc; }

  /* ── FOOTER ── */
  footer {
    text-align: center; padding: 2rem;
    border-top: 1px solid var(--border);
    color: var(--muted); font-size: 0.75rem;
