<script>
// Live stats simulation
const rpsEl      = document.getElementById('rps');
const latencyEl  = document.getElementById('latency');
const sessionsEl = document.getElementById('sessions');
const feedEl     = document.getElementById('feed');

const EVENTS = [
  { icon:'success', sym:'&#10003;', msgs:['GET /api/v1/health — 200 OK','POST /api/v1/sessions — 201','GET /api/v1/dashboard — 200 OK','DELETE /api/v1/cache — 204','PUT /api/v1/config — 200 OK','GET /api/v1/metrics — 200 OK'] },
  { icon:'warn',    sym:'&#9888;',  msgs:['Memory usage > 80% threshold','Queue depth elevated: 1,240 items','Worker #3 response time > 500ms','Cache miss rate: 42%'] },
  { icon:'info',    sym:'&#8505;',  msgs:['Scheduler: cleanup-job started','New session from 10.0.0.45','Config reload triggered','Health check passed'] },
];

function randomBetween(a, b) { return Math.floor(Math.random() * (b - a + 1)) + a; }

function refreshStats() {
  rpsEl.innerHTML = randomBetween(180, 340);
  const lat = randomBetween(22, 80);
  latencyEl.innerHTML = lat + '<span style="font-size:1rem">ms</span>';
  sessionsEl.innerHTML = randomBetween(1400, 2800).toLocaleString();
}

function addFeedItem() {
  const group  = EVENTS[randomBetween(0, EVENTS.length - 1)];
  const msg    = group.msgs[randomBetween(0, group.msgs.length - 1)];
  const times  = ['just now','1s ago','2s ago','3s ago'];
  const t      = times[randomBetween(0, times.length - 1)];
  const el     = document.createElement('div');
  el.className = 'feed-item';
  el.innerHTML = `<div class="feed-icon ${group.icon}">${group.sym}</div><div class="feed-body"><div class="feed-msg">${msg}</div><div class="feed-time">${t}</div></div>`;
  feedEl.insertBefore(el, feedEl.firstChild);
  while (feedEl.children.length > 6) feedEl.removeChild(feedEl.lastChild);
}

setInterval(refreshStats, 4000);
setInterval(addFeedItem, 2500);
</script>
